exact_statements.PqxdhDeploymentHiddenEntry.isQueryBoundP:
theorem isQueryBoundP_of_bind_left {ι₀ : Type} {spec₀ : OracleSpec ι₀} {α β : Type} {p : ι₀ → Prop}
    [DecidablePred p] {oa : OracleComp spec₀ α} {ob : α → OracleComp spec₀ β} {n : ℕ}
    (bound : (oa >>= ob).IsQueryBoundP p n) : oa.IsQueryBoundP p n

definitions.PqxdhDeploymentBackend.ownerFinish:
noncomputable def ownerFinish (index : Nat) (raw : Pqxdh.Bytes) (owner : PqxdhRegistrationSchedule.Owner KemSK) :
    PqxdhRegistrationSchedule.Game KemSK (Option Pqxdh.Bytes) := do
  let result ← PqxdhRegistrationSchedule.onShared (simulateQ (PqxdhRegistrationSchedule.callbacks setup codec)
    (PqxdhBeaconPhase2Publication.nativeOwner codec.frameRead raw owner))
  modify fun current => { current with owners := current.owners.set index result.2 }
  pure result.1

definitions.PqxdhDeploymentFinishErasure.xreveal:
def xreveal (created : PqxdhLiveServerConstruction.Created Unit) (state : XState KemSK Bk n) :
    PqxdhDeploymentLaterServerGame.Reveal :=
  (PqxdhDeploymentLater.revealOf state.base.native.owners state.snap, (some created.seed, state.log))

definitions.PqxdhDeploymentHiddenSplit.withKernel:
def withKernel (kernel : ConcreteRatchetKernel) (staged : PqxdhBeaconPhase2Publication.Staged) :
    PqxdhBeaconPhase2Publication.Staged :=
  { staged with kernel := kernel }

definitions.PqxdhDeploymentHiddenSplit.setPeerKernel:
def setPeerKernel (state : PqxdhServerRegistrationPublication.State Metadata PeerMetadata Consumed) (key : Std.U64)
    (kernel : ConcreteRatchetKernel) : PqxdhServerRegistrationPublication.State Metadata PeerMetadata Consumed :=
  { state with server := { state.server with peers := Function.update state.server.peers key ((state.server.peers key).map fun peer => { peer with kernel := kernel }) } }
